import json,os,glob,re,collections
H=os.path.expanduser('~')
s=json.load(open(H+'/.claude/settings.json')).get('enabledPlugins',{})
d=json.load(open(H+'/.claude/plugins/installed_plugins.json'))['plugins']
rows=[]
def name_of(p):
    try:
        t=open(p).read(3000)
        m=re.search(r'^name:\s*["\']?([^\n"\']+)',t,re.M)
        return m.group(1).strip() if m else os.path.basename(os.path.dirname(p))
    except: return os.path.basename(os.path.dirname(p))
for p in glob.glob(H+'/.claude/skills/*/SKILL.md'): rows.append((name_of(p),'user',p))
for p in glob.glob(H+'/DEV/.claude/skills/*/SKILL.md'): rows.append((name_of(p),'DEV project',p))
for k,v in d.items():
    if not s.get(k): continue
    ip=v[0]['installPath']
    for p in glob.glob(ip+'/**/SKILL.md',recursive=True): rows.append((name_of(p),'plugin '+k,p))
g=collections.defaultdict(list)
for n,src,p in rows: g[n.lower()].append((src,p.replace(H,'~')))
print('total skills',len(rows))
for n,l in sorted(g.items()):
    if len(l)>1:
        print('\n##',n)
        for x in l: print('  ',x)
EOF

